import os
import torch


class Config:
    """
    Global configuration for the Verified Content-Anchored Ensemble (VCAE) pipeline.
    Centralizes all paths, hyperparameters, and model settings.
    """

    # ==========================================
    # Directories & Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    # Working directory for caching intermediate files (parquet/npy)
    WORK_DIR = "./working/idea_optimized"

    # Metadata file paths (generated by the provided metadata script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Output path for submission
    SUBMISSION_DIR = "./submission"
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Data Specification
    # ==========================================
    # The 3 channels used for the input image, strictly respecting Early Fusion
    # T1w is excluded as per the VCAE strategy description.
    MODALITIES = ["FLAIR", "T1wCE", "T2w"]

    # Input image dimensions
    IMG_SIZE = (224, 224)
    NUM_CHANNELS = len(MODALITIES)

    # ==========================================
    # Expert Model Configuration
    # ==========================================
    # Defines the anatomical planes relative to the Center of Mass (CoM)
    # Expert A: Lower plane (CoM - 5)
    # Expert B: Center plane (CoM)
    # Expert C: Upper plane (CoM + 5)
    EXPERTS = {"Expert_A": -5, "Expert_B": 0, "Expert_C": 5}

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42

    # EfficientNet-B0 standard batch size for A100
    BATCH_SIZE = 32

    # Optimizer settings
    LEARNING_RATE = 1e-4
    # Aggressive weight decay to prevent overfitting on small dataset
    WEIGHT_DECAY = 1e-2

    # Regularization
    DROPOUT_RATE = 0.3
    # Slice jitter range (+/- 1 slice) for training augmentation
    SLICE_JITTER = 1

    # Training loop control
    NUM_EPOCHS = 20
    NUM_FOLDS = 5

    # Early Stopping
    PATIENCE = 5

    # ==========================================
    # Compute & Debugging
    # ==========================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    # Debugging flags to control dataset size for rapid testing
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 20

    @classmethod
    def setup(cls):
        """
        Creates necessary working directories.
        Should be called at the start of the pipeline.
        """
        os.makedirs(cls.WORK_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
